from __future__ import annotations

CONTROL_UI = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>TITAN · Ableton Production Console</title>
<style>
:root{color-scheme:dark;--bg:#080a0b;--panel:#111518;--panel2:#171c20;--line:#293137;--text:#eef2f3;--muted:#88949b;--green:#61f2b5;--amber:#f1b84b;--red:#ff6969;--blue:#6ea8ff;--purple:#b38cff;font-family:Inter,Segoe UI,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#12231d 0,transparent 28%),var(--bg);color:var(--text)}button,input,select,textarea{font:inherit}.shell{display:grid;grid-template-columns:230px minmax(0,1fr);min-height:100vh}.side{position:sticky;top:0;height:100vh;border-right:1px solid var(--line);background:rgba(9,12,13,.95);padding:22px 16px}.brand{font-weight:900;letter-spacing:.13em;font-size:16px}.brand span{color:var(--green)}.sub{font-size:11px;color:var(--muted);margin:6px 0 25px}.nav button{width:100%;text-align:left;border:0;background:transparent;color:var(--muted);padding:11px 12px;border-radius:8px;margin:2px 0;cursor:pointer}.nav button.active,.nav button:hover{background:var(--panel2);color:#fff}.side-foot{position:absolute;bottom:18px;left:16px;right:16px}.token{width:100%;background:#0b0e10;border:1px solid var(--line);color:#fff;padding:9px;border-radius:7px}.main{padding:24px 28px 42px;min-width:0}.top{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:20px}.eyebrow{font-size:11px;color:var(--green);font-weight:800;letter-spacing:.16em}.top h1{font-size:25px;margin:5px 0 0}.status-row{display:flex;gap:8px;flex-wrap:wrap}.pill{border:1px solid var(--line);background:var(--panel);padding:8px 11px;border-radius:999px;font-size:12px;color:var(--muted)}.pill.ok{color:var(--green);border-color:#265942}.pill.warn{color:var(--amber);border-color:#624c21}.view{display:none}.view.active{display:block}.grid{display:grid;gap:12px}.metrics{grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:14px}.card{background:linear-gradient(180deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:12px;padding:15px}.metric label{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.metric b{display:block;font-size:21px;margin-top:7px}.section-title{display:flex;align-items:end;justify-content:space-between;margin:24px 0 10px}.section-title h2{font-size:16px;margin:0}.section-title p{font-size:12px;color:var(--muted);margin:0}.transport{display:grid;grid-template-columns:160px 1fr auto;gap:12px;align-items:end}.field label{display:block;color:var(--muted);font-size:11px;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;background:#0b0e10;border:1px solid var(--line);color:#fff;border-radius:8px;padding:10px}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#20262a;color:#fff;border-radius:8px;padding:9px 13px;font-weight:750;cursor:pointer}.btn:hover{filter:brightness(1.14)}.btn.primary{background:var(--green);color:#07120d;border-color:transparent}.btn.amber{background:var(--amber);color:#171005;border-color:transparent}.btn.red{background:#4b2023;color:#ffb0b0}.mixer{display:grid;grid-template-columns:repeat(6,minmax(145px,1fr));gap:10px}.strip{background:#101417;border:1px solid var(--line);border-radius:10px;padding:12px;min-width:0}.strip-head{height:47px}.strip-name{font-size:12px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.strip-role{font-size:10px;color:var(--muted);margin-top:4px}.control{margin-top:10px}.control label{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin-bottom:5px}.control input[type=range]{width:100%;accent-color:var(--green)}.mini-actions{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:9px}.mini{border:1px solid var(--line);background:#1a2024;color:#bac3c8;border-radius:6px;padding:6px;cursor:pointer;font-size:10px}.mini.on{background:#513f18;color:#ffd875}.sends{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-top:8px}.send{font-size:9px;color:var(--muted)}.send input{width:100%;accent-color:var(--blue)}.returns{grid-template-columns:repeat(4,minmax(180px,1fr))}.return-card{position:relative;overflow:hidden}.return-card:before{content:"";position:absolute;inset:0 auto 0 0;width:3px;background:var(--blue)}.return-card:nth-child(2):before{background:var(--amber)}.return-card:nth-child(3):before{background:var(--purple)}.return-card:nth-child(4):before{background:var(--red)}.chain{font-family:Consolas,monospace;font-size:11px;color:#b9c4ca;background:#0b0e10;border-radius:6px;padding:8px;margin:10px 0}.quick-grid{grid-template-columns:repeat(3,1fr)}textarea.code{min-height:155px;font-family:Consolas,monospace;resize:vertical}.history{display:flex;flex-direction:column;gap:8px}.event{display:grid;grid-template-columns:110px 150px 1fr auto;gap:12px;align-items:center;background:#101417;border:1px solid var(--line);border-radius:9px;padding:10px 12px;font-size:11px}.event code{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#c7d1d5}.state{font-weight:800}.state.acknowledged{color:var(--green)}.state.error{color:var(--red)}.state.pending{color:var(--amber)}.error{color:var(--red);font-size:12px;margin:9px 0}.notice{background:#17241f;border:1px solid #265942;color:#a9e9cd;padding:10px 12px;border-radius:8px;font-size:12px;margin:10px 0}.hidden{display:none}@media(max-width:1200px){.mixer{grid-template-columns:repeat(4,minmax(145px,1fr))}.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:840px){.shell{grid-template-columns:1fr}.side{position:relative;height:auto;border-right:0;border-bottom:1px solid var(--line)}.nav{display:flex;overflow:auto}.nav button{width:auto;white-space:nowrap}.side-foot{position:static;margin-top:12px}.main{padding:20px 14px}.top{align-items:flex-start;flex-direction:column}.mixer{grid-template-columns:repeat(2,minmax(135px,1fr))}.returns,.quick-grid{grid-template-columns:1fr}.transport{grid-template-columns:1fr}.event{grid-template-columns:1fr}}
</style>
</head>
<body>
<div class="shell">
<aside class="side">
  <div class="brand"><span>TITAN</span> CONTROL</div><div class="sub">ABLETON LIVE 11 PRODUCTION SYSTEM</div>
  <nav class="nav">
    <button class="active" data-view="overview">Overview</button>
    <button data-view="mixer">12-Stem Mixer</button>
    <button data-view="returns">Returns A–D</button>
    <button data-view="commands">Command Center</button>
    <button data-view="history">History & ACK</button>
  </nav>
  <div class="side-foot"><input id="token" class="token" type="password" placeholder="Local bridge token"></div>
</aside>
<main class="main">
<header class="top"><div><div class="eyebrow">CANONICAL DARK TECHNO SESSION</div><h1>Ableton Production Console</h1></div><div class="status-row"><span id="bridgePill" class="pill warn">Bridge checking</span><span id="receiverPill" class="pill warn">Receiver checking</span><span id="modePill" class="pill">Mode</span></div></header>
<p id="globalError" class="error"></p>
<section id="overview" class="view active">
  <div class="grid metrics"><div class="card metric"><label>Bridge</label><b id="bridgeMetric">—</b></div><div class="card metric"><label>Receiver</label><b id="receiverMetric">—</b></div><div class="card metric"><label>Commands</label><b id="commandMetric">0</b></div><div class="card metric"><label>Last ACK</label><b id="ackMetric">—</b></div></div>
  <div class="card transport"><div class="field"><label>Tempo</label><input id="tempo" type="number" min="20" max="300" value="128"></div><div class="actions"><button class="btn primary" onclick="setTempo()">SET TEMPO</button><button class="btn" onclick="simple('start_playback')">PLAY</button><button class="btn" onclick="simple('stop_playback')">STOP</button><button class="btn red" onclick="simple('stop_all_clips')">STOP ALL CLIPS</button></div><button class="btn amber" onclick="refreshAll()">REFRESH STATUS</button></div>
  <div class="section-title"><div><h2>Canonical architecture</h2><p>12 stems · 4 returns · 128 BPM · F minor</p></div></div>
  <div class="grid quick-grid"><div class="card"><b>DRUMS + LOW END</b><div class="chain">Kick · Round Bass · Percussion · Groove Hat · Open Hat</div><span class="sub">Stable center, controlled room, parallel drive.</span></div><div class="card"><b>MUSIC</b><div class="chain">Synth Stab · Melody · Pad</div><span class="sub">Question/answer structure and evolving voicings.</span></div><div class="card"><b>FX + ATMOS</b><div class="chain">Riser · Impact · Voice · Ambient</div><span class="sub">Transitions, depth and narrative punctuation.</span></div></div>
  <div class="notice">Master chain remains intentionally conservative and is applied only after dense-section headroom is confirmed near −6 dBFS.</div>
</section>
<section id="mixer" class="view"><div class="section-title"><div><h2>12-Stem Mixer</h2><p>Volume, pan, mute, solo and sends to A–D</p></div><button class="btn primary" onclick="applyPremix()">APPLY CANONICAL PREMIX</button></div><div id="mixerGrid" class="mixer"></div></section>
<section id="returns" class="view"><div class="section-title"><div><h2>Return Architecture</h2><p>Indices are stable: A=0, B=1, C=2, D=3</p></div></div><div id="returnGrid" class="grid returns"></div></section>
<section id="commands" class="view"><div class="section-title"><div><h2>Command Center</h2><p>Fast operations and full JSON control</p></div></div><div class="grid quick-grid"><div class="card"><b>Session</b><div class="actions" style="margin-top:12px"><button class="btn" onclick="simple('set_metronome',{enabled:true})">Metronome On</button><button class="btn" onclick="simple('set_metronome',{enabled:false})">Off</button></div></div><div class="card"><b>Scene</b><div class="field" style="margin-top:10px"><label>Scene index</label><input id="sceneIndex" type="number" min="0" value="0"></div><button class="btn primary" style="margin-top:8px" onclick="launchScene()">LAUNCH</button></div><div class="card"><b>Loop</b><div class="actions" style="margin-top:12px"><button class="btn" onclick="simple('set_song_loop',{start:0,length:32,enabled:true})">32 Beats</button><button class="btn" onclick="simple('set_song_loop',{start:0,length:64,enabled:true})">64 Beats</button><button class="btn red" onclick="simple('set_song_loop',{start:0,length:4,enabled:false})">Off</button></div></div></div><div class="card" style="margin-top:12px"><div class="field"><label>Raw JSON command</label><textarea id="jsonCommand" class="code" spellcheck="false">{"type":"set_tempo","bpm":128}</textarea></div><div class="actions" style="margin-top:10px"><button class="btn primary" onclick="sendRaw()">EXECUTE JSON</button><button class="btn" onclick="formatJson()">FORMAT</button></div></div></section>
<section id="history" class="view"><div class="section-title"><div><h2>History & ACK</h2><p>Every command, Ableton response and failure</p></div><button class="btn" onclick="loadHistory()">REFRESH</button></div><div id="historyList" class="history"></div></section>
</main></div>
<script>
const stems=[
 {ref:'kick',name:'01 KICK',role:'Operator · punch',vol:.82,pan:0,sends:[0,.01,.01,.08]},
 {ref:'bass',name:'02 ROUND BASS',role:'Operator · low end',vol:.76,pan:0,sends:[.02,.02,.01,.03]},
 {ref:'percussion',name:'03 PERCUSSION',role:'Drum Rack · groove',vol:.61,pan:-.06,sends:[.14,.03,.02,.18]},
 {ref:'closed_hats',name:'04 GROOVE HAT',role:'Closed hat · swing',vol:.52,pan:.12,sends:[.10,.03,.02,.08]},
 {ref:'open_hats',name:'05 OPEN HAT',role:'Open hat · air',vol:.47,pan:-.16,sends:[.13,.05,.04,.02]},
 {ref:'synth_stab',name:'06 SYNTH STAB',role:'Wavetable · rhythm',vol:.56,pan:.08,sends:[.08,.10,.07,.11]},
 {ref:'melody',name:'07 MELODY',role:'Wavetable · question/answer',vol:.53,pan:-.07,sends:[.07,.12,.09,.03]},
 {ref:'pad',name:'08 PAD',role:'Drift · harmony',vol:.42,pan:.10,sends:[.04,.04,.16,.01]},
 {ref:'fx_riser',name:'09 FX RISER',role:'Transitions · movement',vol:.40,pan:.15,sends:[.04,.08,.14,0]},
 {ref:'fx_impact',name:'10 FX IMPACT',role:'Impacts · punctuation',vol:.48,pan:-.05,sends:[.06,.03,.08,.04]},
 {ref:'voice',name:'11 VOICE',role:'Vocal · presence',vol:.50,pan:0,sends:[.12,.15,.12,.03]},
 {ref:'ambient',name:'12 AMBIENT',role:'Texture · atmosphere',vol:.36,pan:-.12,sends:[.03,.03,.20,0]}
];
const returns=[
 {i:0,name:'A SHORT ROOM',chain:'Reverb',purpose:'Short cohesion · 29.30 ms predelay · ~351 ms tail',vol:.34},
 {i:1,name:'B DUB DELAY',chain:'Echo',purpose:'Tempo-synced stereo dub delay',vol:.28},
 {i:2,name:'C LONG SPACE',chain:'Hybrid Reverb',purpose:'Long depth for pad, voice and ambience',vol:.25},
 {i:3,name:'D PARALLEL DRIVE',chain:'Drum Buss → Glue Compressor → EQ Eight',purpose:'Parallel density for rhythm and stabs',vol:.20}
];
const qs=s=>document.querySelector(s),qsa=s=>[...document.querySelectorAll(s)];const params=new URLSearchParams(location.search);const token=qs('#token');token.value=params.get('token')||localStorage.bridgeToken||'';if(params.get('token')){localStorage.bridgeToken=token.value;history.replaceState({},'',location.pathname)}token.onchange=()=>{localStorage.bridgeToken=token.value;refreshAll()};const headers=()=>({'X-Bridge-Token':token.value});
qsa('.nav button').forEach(b=>b.onclick=()=>{qsa('.nav button').forEach(x=>x.classList.remove('active'));qsa('.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');qs('#'+b.dataset.view).classList.add('active');if(b.dataset.view==='history')loadHistory()});
function showError(e){qs('#globalError').textContent=e?.message||String(e)}async function command(payload){const r=await fetch('/command',{method:'POST',headers:{...headers(),'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw Error(data.error||'Command rejected');qs('#globalError').textContent='';return data.command}
async function simple(type,extra={}){try{await command({type,...extra});setTimeout(refreshAll,300)}catch(e){showError(e)}}async function setTempo(){return simple('set_tempo',{bpm:Number(qs('#tempo').value)})}async function launchScene(){return simple('launch_scene',{scene:Number(qs('#sceneIndex').value)})}
function renderMixer(){qs('#mixerGrid').innerHTML=stems.map((s,n)=>`<article class="strip"><div class="strip-head"><div class="strip-name">${s.name}</div><div class="strip-role">${s.role}</div></div><div class="control"><label><span>VOL</span><span id="v${n}">${s.vol.toFixed(2)}</span></label><input type="range" min="0" max="1" step=".01" value="${s.vol}" oninput="v${n}.textContent=this.value" onchange="setStem('${s.ref}','set_track_volume','volume',this.value)"></div><div class="control"><label><span>PAN</span><span id="p${n}">${s.pan.toFixed(2)}</span></label><input type="range" min="-1" max="1" step=".01" value="${s.pan}" oninput="p${n}.textContent=this.value" onchange="setStem('${s.ref}','set_track_pan','pan',this.value)"></div><div class="mini-actions"><button class="mini" onclick="toggle(this,'${s.ref}','mute')">MUTE</button><button class="mini" onclick="toggle(this,'${s.ref}','solo')">SOLO</button></div><div class="sends">${s.sends.map((v,i)=>`<label class="send">${'ABCD'[i]}<input type="range" min="0" max=".5" step=".01" value="${v}" onchange="setSend('${s.ref}',${i},this.value)"></label>`).join('')}</div></article>`).join('')}
async function setStem(ref,type,key,value){try{await command({type,track_ref:ref,[key]:Number(value)})}catch(e){showError(e)}}async function setSend(ref,i,value){try{await command({type:'set_track_send',track_ref:ref,return:i,amount:Number(value)})}catch(e){showError(e)}}async function toggle(btn,ref,kind){btn.classList.toggle('on');const on=btn.classList.contains('on');await simple(kind==='mute'?'set_track_mute':'set_track_solo',{track_ref:ref,[kind==='mute'?'muted':'soloed']:on})}
function renderReturns(){qs('#returnGrid').innerHTML=returns.map(r=>`<article class="card return-card"><b>${r.name}</b><div class="chain">${r.chain}</div><p class="sub">${r.purpose}</p><div class="control"><label><span>RETURN LEVEL</span><span id="rv${r.i}">${r.vol.toFixed(2)}</span></label><input type="range" min="0" max="1" step=".01" value="${r.vol}" oninput="rv${r.i}.textContent=this.value" onchange="setReturn(${r.i},this.value)"></div></article>`).join('')}async function setReturn(i,value){try{await command({type:'set_return_volume',return:i,volume:Number(value)})}catch(e){showError(e)}}
async function applyPremix(){for(const s of stems){await command({type:'set_track_volume',track_ref:s.ref,volume:s.vol});await command({type:'set_track_pan',track_ref:s.ref,pan:s.pan})}refreshAll()}
async function sendRaw(){try{await command(JSON.parse(qs('#jsonCommand').value));setTimeout(refreshAll,300)}catch(e){showError(e)}}function formatJson(){try{qs('#jsonCommand').value=JSON.stringify(JSON.parse(qs('#jsonCommand').value),null,2)}catch(e){showError(e)}}
async function action(id,name){try{const r=await fetch(`/api/commands/${id}/${name}`,{method:'POST',headers:headers()});const d=await r.json();if(!r.ok)throw Error(d.error);loadHistory()}catch(e){showError(e)}}
async function loadHistory(){try{const r=await fetch('/api/commands?limit=100',{headers:headers()});const d=await r.json();if(!r.ok)throw Error(d.error);qs('#commandMetric').textContent=d.commands.length;qs('#historyList').innerHTML=d.commands.map(c=>`<div class="event"><span class="state ${c.status}">${c.status}</span><b>${c.command_type}</b><code>${JSON.stringify(c.payload)}</code><span>${c.status==='pending'?`<button class="mini" onclick="action('${c.id}','approve')">Approve</button><button class="mini" onclick="action('${c.id}','reject')">Reject</button>`:['sent','acknowledged'].includes(c.status)?`<button class="mini" onclick="action('${c.id}','undo')">Undo</button>`:''}</span>${c.error?`<div class="error" style="grid-column:1/-1">${c.error}</div>`:''}</div>`).join('')||'<p class="sub">No commands yet.</p>'}catch(e){showError(e)}}
async function refreshAll(){try{const h=await fetch('/health').then(r=>r.json());qs('#bridgeMetric').textContent=`v${h.version}`;qs('#receiverMetric').textContent=h.max_receiver_seen?'CONNECTED':'WAITING';qs('#ackMetric').textContent=h.last_ack_at?new Date(h.last_ack_at).toLocaleTimeString():'—';qs('#bridgePill').textContent=`Bridge v${h.version}`;qs('#bridgePill').className='pill ok';qs('#receiverPill').textContent=h.max_receiver_seen?'Receiver connected':'Receiver waiting';qs('#receiverPill').className='pill '+(h.max_receiver_seen?'ok':'warn');qs('#modePill').textContent=h.approval_required?'Approval mode':'Autonomous mode';await loadHistory()}catch(e){qs('#bridgePill').textContent='Bridge offline';qs('#bridgePill').className='pill warn';showError(e)}}
renderMixer();renderReturns();refreshAll();setInterval(refreshAll,3000);
</script>
</body></html>'''
